def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--install", action="store_true")
    args = parser.parse_args()

    if not SHOCK.is_file() or not CMAKE.is_file():
        print("ERROR: run from the Shockolate project root.", file=sys.stderr)
        return 1

    current_shock = SHOCK.read_text(encoding="utf-8")
    current_cmake = CMAKE.read_text(encoding="utf-8")

    if "PROJECT CITADEL V15G: fresh texture binding test is ACTIVE" not in current_shock:
        print("ERROR: active Shock.c is not the supplied V15G source.", file=sys.stderr)
        return 1

    if "PROJECT CITADEL V15H" in current_shock or "citadel_v15h_control_asset" in current_cmake:
        print("ERROR: V15H already appears installed.", file=sys.stderr)
        return 1

    Path("Shock_3DS_V15H_official_tex3ds_control.c").write_text(
        V15H_SHOCK, encoding="utf-8", newline="\n")
    Path("CMakeLists_V15H_preview.txt").write_text(
        V15H_CMAKE, encoding="utf-8", newline="\n")
    Path("V15H_CONTROL.png").write_bytes(PNG_BYTES)

    print("Created previews:")
    print("  Shock_3DS_V15H_official_tex3ds_control.c")
    print("  CMakeLists_V15H_preview.txt")
    print("  V15H_CONTROL.png")

    if not args.install:
        print("Active project files were not changed.")
        print("Install with:")
        print("  python apply_SS3DS_V15H_official_tex3ds_control.py --install")
        return 0

    if BACKUP_SHOCK.exists() or BACKUP_CMAKE.exists():
        print("ERROR: a V15H backup file already exists.", file=sys.stderr)
        return 1

    shutil.copy2(SHOCK, BACKUP_SHOCK)
    shutil.copy2(CMAKE, BACKUP_CMAKE)
    SHOCK.write_text(V15H_SHOCK, encoding="utf-8", newline="\n")
    CMAKE.write_text(V15H_CMAKE, encoding="utf-8", newline="\n")
    ASSET.parent.mkdir(parents=True, exist_ok=True)
    ASSET.write_bytes(PNG_BYTES)

    print(f"Installed {SHOCK}")
    print(f"Installed {CMAKE}")
    print(f"Installed {ASSET}")
    print(f"Backup {BACKUP_SHOCK}")
    print(f"Backup {BACKUP_CMAKE}")
    print()
    print("Build with:")
    print("  cmake --build build-3ds")
    print()
    print("Then copy BOTH files to /3ds/systemshock/:")
    print("  build-3ds/systemshock.3dsx")
    print("  build-3ds/V15H_CONTROL.t3x")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
